from pathlib import PurePosixPath

def a_serializable(obj):
    if isinstance(obj, date):             # también acepta datetime (deriva de date)
        return obj.isoformat()
    if isinstance(obj, (set, frozenset)):  # isinstance admite una tupla de tipos
        return sorted(obj)
