def copiar_por_bloques(origen, destino, tam_bloque=4096):
    if tam_bloque <= 0:
        raise ValueError(f"tam_bloque debe ser positivo, no {tam_bloque}")
    bloques = 0
    with open(origen, "rb") as fuente, open(destino, "wb") as copia:
        while bloque := fuente.read(tam_bloque):
            copia.write(bloque)
            bloques += 1
    return bloques

