from pathlib import Path

SIN_EXTENSION = "(sin extensión)"


def contar_extensiones(carpeta):
    raiz = Path(carpeta)
    if not raiz.exists():
        raise FileNotFoundError(f"No existe: {raiz}")
    if not raiz.is_dir():
        raise NotADirectoryError(f"No es una carpeta: {raiz}")

    conteo = {}
    for ruta in raiz.rglob("*"):
        if ruta.is_file():
            extension = ruta.suffix.lower().lstrip(".") or SIN_EXTENSION
            conteo[extension] = conteo.get(extension, 0) + 1

    ordenado = sorted(conteo.items(), key=lambda par: (-par[1], par[0]))
    return dict(ordenado)

