import csv


def a_numero(texto):
    """Convierte '2,50' (coma decimal) en 2.5."""
    return float(texto.replace(",", "."))


def resumen_ventas(ruta):
    totales = {}
    unidades_totales = 0
    with open(ruta, newline="", encoding="utf-8-sig") as f:
        for fila in csv.DictReader(f, delimiter=";"):
            producto = fila["producto"]
            unidades = int(fila["unidades"])
            importe = unidades * a_numero(fila["precio_unitario"])
            totales[producto] = totales.get(producto, 0) + importe
            unidades_totales += unidades

    totales = {producto: round(total, 2) for producto, total in totales.items()}
    estrella = max(totales, key=totales.get) if totales else None
    return {"totales": totales, "unidades": unidades_totales, "estrella": estrella}

