import csv
import json
import re

ENTERO = re.compile(r"-?[0-9]+")
DECIMAL = re.compile(r"-?[0-9]+\.[0-9]+")


def convertir_valor(texto):
    if texto == "":
        return None
    if texto.lower() in ("true", "false"):
        return texto.lower() == "true"
    if ENTERO.fullmatch(texto):
        return int(texto)
    if DECIMAL.fullmatch(texto):
        return float(texto)
    return texto


def csv_a_json(ruta_csv, ruta_json):
    registros = []
    with open(ruta_csv, newline="", encoding="utf-8") as f:
        for fila in csv.DictReader(f):
            registros.append({columna: convertir_valor(valor) for columna, valor in fila.items()})
    with open(ruta_json, "w", encoding="utf-8") as f:
        json.dump(registros, f, indent=2, ensure_ascii=False)
    return len(registros)

