import json
from datetime import date, datetime
from decimal import Decimal


def codificar(obj):
    """default: solo recibe lo que json no sabe serializar."""
    if isinstance(obj, datetime):          # ¡antes que date!: un datetime también es un date
        return {"__fechahora__": obj.isoformat()}
    if isinstance(obj, date):
        return {"__fecha__": obj.isoformat()}
    if isinstance(obj, (set, frozenset)):
        return {"__conjunto__": sorted(obj)}
    if isinstance(obj, Decimal):
        return {"__decimal__": str(obj)}
    raise TypeError(f"Un objeto de tipo {type(obj).__name__} no se puede convertir a JSON")


DECODIFICADORES = {
    "__fechahora__": datetime.fromisoformat,
    "__fecha__": date.fromisoformat,
    "__conjunto__": set,
    "__decimal__": Decimal,
}


def decodificar(objeto):
    """object_hook: recibe cada objeto JSON ya convertido en dict."""
    if len(objeto) == 1:
        for etiqueta, reconstruir in DECODIFICADORES.items():
            if etiqueta in objeto:
                return reconstruir(objeto[etiqueta])
    return objeto


def a_json(datos):
    return json.dumps(datos, default=codificar, ensure_ascii=False)


def desde_json(texto):
    return json.loads(texto, object_hook=decodificar)

