from datetime import date


def comprobar_orden(nacimiento, hoy):
    if nacimiento > hoy:
        raise ValueError("La fecha de nacimiento no puede ser posterior a hoy")


def calcular_edad(nacimiento, hoy):
    comprobar_orden(nacimiento, hoy)
    edad = hoy.year - nacimiento.year
    if (hoy.month, hoy.day) < (nacimiento.month, nacimiento.day):
        edad -= 1          # este año todavía no ha cumplido
    return edad


def cumpleanos_en(nacimiento, anio):
    """Fecha del cumpleaños en 'anio' (29-feb -> 1-mar si el año no es bisiesto)."""
    try:
        return nacimiento.replace(year=anio)
    except ValueError:
        return date(anio, 3, 1)


def proximo_cumpleanos(nacimiento, hoy):
    comprobar_orden(nacimiento, hoy)
    siguiente = cumpleanos_en(nacimiento, hoy.year)
    if siguiente < hoy:
        siguiente = cumpleanos_en(nacimiento, hoy.year + 1)
    return (siguiente - hoy).days

