import sqlite3


def crear_tabla(con):
    con.execute(
        "CREATE TABLE IF NOT EXISTS contactos ("
        " id INTEGER PRIMARY KEY,"
        " nombre TEXT NOT NULL,"
        " email TEXT NOT NULL UNIQUE)"
    )
    con.commit()


def agregar(con, nombre, email):
    try:
        with con:                                   # commit o rollback automático
            cur = con.execute(
                "INSERT INTO contactos (nombre, email) VALUES (?, ?)",
                (nombre, email),
            )
    except sqlite3.IntegrityError as error:
        raise ValueError(f"Ya existe un contacto con el email {email!r}") from error
    return cur.lastrowid


def buscar(con, texto):
    cur = con.execute(
        "SELECT nombre, email FROM contactos WHERE nombre LIKE ? ORDER BY id",
        (f"%{texto}%",),                            # el patrón es un VALOR, no SQL
    )
    return cur.fetchall()


def borrar(con, email):
    with con:
        cur = con.execute("DELETE FROM contactos WHERE email = ?", (email,))
    return cur.rowcount == 1

