from datetime import datetime, timezone

NIVELES = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}


def interpretar_linea(linea):
    """Devuelve (instante en UTC, nivel) o None si la línea no es válida."""
    partes = linea.split(maxsplit=2)       # fecha, nivel y el resto (el mensaje)
    if len(partes) < 3:
        return None
    texto_fecha, nivel = partes[0], partes[1].upper()
    if nivel not in NIVELES:
        return None
    try:
        instante = datetime.fromisoformat(texto_fecha)
    except ValueError:
        return None
    if instante.tzinfo is None:            # ingenua: no sabemos qué instante es
        return None
    return instante.astimezone(timezone.utc), nivel


def analizar_log(ruta):
    total = invalidas = 0
    por_nivel = {}
    primero = ultimo = None
    with open(ruta, encoding="utf-8") as f:
        for linea in f:                    # una línea en memoria cada vez
            if not linea.strip():
                continue
            resultado = interpretar_linea(linea)
            if resultado is None:
                invalidas += 1
                continue
            instante, nivel = resultado
            total += 1
            por_nivel[nivel] = por_nivel.get(nivel, 0) + 1
            if primero is None or instante < primero:
                primero = instante
            if ultimo is None or instante > ultimo:
                ultimo = instante

    if total == 0:
        return {"total": 0, "invalidas": invalidas, "por_nivel": {},
                "primero": None, "ultimo": None, "duracion_min": 0.0}
    return {
        "total": total,
        "invalidas": invalidas,
        "por_nivel": por_nivel,
        "primero": primero.isoformat(),
        "ultimo": ultimo.isoformat(),
        "duracion_min": (ultimo - primero).total_seconds() / 60,
    }

