import re
from datetime import datetime, time, timedelta, timezone

PATRON_DESFASE = re.compile(r"([+-])([0-9]{2}):([0-9]{2})")
MINIMO, MAXIMO = timedelta(hours=-12), timedelta(hours=14)
APERTURA, CIERRE = time(9, 0), time(18, 0)


def zona_desde_texto(texto):
    """'+05:30' -> timezone(timedelta(hours=5, minutes=30))"""
    coincidencia = PATRON_DESFASE.fullmatch(texto)
    if coincidencia is None:
        raise ValueError(f"Desfase no válido: {texto!r} (formato ±HH:MM)")
    signo, horas, minutos = coincidencia.groups()
    if int(minutos) >= 60:
        raise ValueError(f"Minutos no válidos en {texto!r}")
    desfase = timedelta(hours=int(horas), minutes=int(minutos))
    if signo == "-":
        desfase = -desfase
    if not MINIMO <= desfase <= MAXIMO:
        raise ValueError(f"Desfase fuera de rango: {texto!r}")
    return timezone(desfase)


def es_laborable(ini, fin):
    return (
        ini.weekday() < 5
        and ini.date() == fin.date()
        and ini.time() >= APERTURA
        and fin.time() <= CIERRE
    )


def planificar_reunion(inicio, duracion_min, participantes):
    comienzo = datetime.fromisoformat(inicio)          # ValueError si no es ISO 8601
    if comienzo.tzinfo is None:
        raise ValueError("La hora de inicio debe incluir la zona horaria")
    if duracion_min <= 0:
        raise ValueError("La duración debe ser positiva")
    final = comienzo + timedelta(minutes=duracion_min)

    agenda = {}
    for nombre, texto_zona in participantes.items():
        zona = zona_desde_texto(texto_zona)
        ini_local = comienzo.astimezone(zona)          # mismo instante, otra hora de pared
        fin_local = final.astimezone(zona)
        agenda[nombre] = {
            "inicio": f"{ini_local:%Y-%m-%d %H:%M}",
            "fin": f"{fin_local:%Y-%m-%d %H:%M}",
            "laborable": es_laborable(ini_local, fin_local),
        }
    return agenda

