import csv
import sqlite3

SQL_PRODUCTOS = """
CREATE TABLE IF NOT EXISTS productos (
    sku    TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    precio REAL NOT NULL CHECK (precio >= 0),
    stock  INTEGER NOT NULL CHECK (stock >= 0)
)"""

SQL_MOVIMIENTOS = """
CREATE TABLE IF NOT EXISTS movimientos (
    id       INTEGER PRIMARY KEY,
    sku      TEXT NOT NULL REFERENCES productos (sku),
    cantidad INTEGER NOT NULL,
    fecha    TEXT NOT NULL
)"""


def abrir_inventario(ruta):
    con = sqlite3.connect(ruta)
    with con:
        con.execute(SQL_PRODUCTOS)
        con.execute(SQL_MOVIMIENTOS)
    return con


def alta_producto(con, sku, nombre, precio, stock=0):
    if precio < 0 or stock < 0:
        raise ValueError("El precio y el stock no pueden ser negativos")
    try:
        with con:
            con.execute(
                "INSERT INTO productos (sku, nombre, precio, stock) VALUES (?, ?, ?, ?)",
                (sku, nombre, precio, stock),
            )
    except sqlite3.IntegrityError as error:
        raise ValueError(f"Ya existe un producto con SKU {sku!r}") from error


def mover_stock(con, sku, cantidad, fecha):
    if cantidad == 0:
        raise ValueError("La cantidad de un movimiento no puede ser 0")
    with con:                                   # todo o nada
        fila = con.execute("SELECT stock FROM productos WHERE sku = ?", (sku,)).fetchone()
        if fila is None:
            raise KeyError(sku)
        nuevo = fila[0] + cantidad
        if nuevo < 0:
            raise ValueError(f"Stock insuficiente de {sku}: hay {fila[0]} y se piden {-cantidad}")
        con.execute("UPDATE productos SET stock = ? WHERE sku = ?", (nuevo, sku))
        con.execute(
            "INSERT INTO movimientos (sku, cantidad, fecha) VALUES (?, ?, ?)",
            (sku, cantidad, fecha.isoformat()),
        )
    return nuevo


def historial(con, sku):
    cur = con.execute(
        "SELECT fecha, cantidad FROM movimientos WHERE sku = ? ORDER BY id", (sku,)
    )
    return cur.fetchall()


def valor_inventario(con):
    total = con.execute("SELECT SUM(precio * stock) FROM productos").fetchone()[0]
    if total is None:                           # SUM de una tabla vacía es NULL
        return 0.0
    return round(total, 2)


def bajo_minimo(con, minimo):
    cur = con.execute(
        "SELECT sku FROM productos WHERE stock < ? ORDER BY stock, sku", (minimo,)
    )
    return [fila[0] for fila in cur]


def exportar_csv(con, ruta_csv):
    filas = con.execute(
        "SELECT sku, nombre, precio, stock FROM productos ORDER BY sku"
    ).fetchall()
    with open(ruta_csv, "w", newline="", encoding="utf-8") as f:
        escritor = csv.writer(f)
        escritor.writerow(["sku", "nombre", "precio", "stock"])
        escritor.writerows(filas)
    return len(filas)

