import json
import zipfile
from pathlib import Path, PurePosixPath

MANIFIESTO = "manifiesto.json"


def crear_copia(origen, destino_zip, excluir=()):
    raiz = Path(origen)
    if not raiz.exists():
        raise FileNotFoundError(f"No existe: {raiz}")
    if not raiz.is_dir():
        raise NotADirectoryError(f"No es una carpeta: {raiz}")

    excluidas = {extension.lower() for extension in excluir}
    seleccion = []
    for ruta in raiz.rglob("*"):
        if ruta.is_file() and ruta.suffix.lower() not in excluidas:
            seleccion.append((ruta.relative_to(raiz).as_posix(), ruta))
    seleccion.sort()                       # por ruta relativa (cadena)

    manifiesto = {"archivos": [], "total_bytes": 0}
    with zipfile.ZipFile(destino_zip, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for relativa, ruta in seleccion:
            zf.write(ruta, arcname=relativa)
            tamanio = ruta.stat().st_size
            manifiesto["archivos"].append({"ruta": relativa, "bytes": tamanio})
            manifiesto["total_bytes"] += tamanio
        zf.writestr(MANIFIESTO, json.dumps(manifiesto, indent=2, ensure_ascii=False))
    return len(seleccion)


def verificar_copia(destino_zip):
    with zipfile.ZipFile(destino_zip) as zf:
        nombres = set(zf.namelist())
        if MANIFIESTO not in nombres:
            return ["falta manifiesto.json"]
        manifiesto = json.loads(zf.read(MANIFIESTO))
        nombres.discard(MANIFIESTO)
        problemas = []
        for entrada in manifiesto["archivos"]:
            ruta = entrada["ruta"]
            if ruta not in nombres:
                problemas.append(f"falta {ruta}")
            elif zf.getinfo(ruta).file_size != entrada["bytes"]:
                problemas.append(f"tamaño distinto: {ruta}")
            nombres.discard(ruta)
        for sobrante in sorted(nombres):
            problemas.append(f"sobra {sobrante}")
    return problemas


def es_nombre_seguro(nombre):
    ruta = PurePosixPath(nombre)
    return not ruta.is_absolute() and ".." not in ruta.parts


def restaurar_copia(destino_zip, carpeta_destino):
    destino = Path(carpeta_destino)
    with zipfile.ZipFile(destino_zip) as zf:
        nombres = [n for n in zf.namelist() if n != MANIFIESTO and not n.endswith("/")]
        peligrosos = [n for n in nombres if not es_nombre_seguro(n)]
        if peligrosos:                      # validar TODO antes de escribir NADA
            raise ValueError(f"Rutas peligrosas en el ZIP: {peligrosos}")
        for nombre in nombres:
            ruta = destino / nombre
            ruta.parent.mkdir(parents=True, exist_ok=True)
            ruta.write_bytes(zf.read(nombre))
    return len(nombres)

